def solve():
    from math import isqrt
    x = abs(int(input()))
    k = isqrt(2 * x)
    while k * (k + 1) // 2 < x:
        k += 1
    location = k * (k + 1) // 2
    diff = location - x
    if diff % 2 == 0:
        print(k)
    elif (diff - (k + 1)) % 2 == 0:
        print(k + 1)
    else:
        print(k + 2)


