def solve(csc, x):
    for i in range(45000 + 1):
        if x == csc[i]:
            return i
        elif x < csc[i]:
            diff = csc[i] - x
            if diff % 2 == 0:
                return i
            diff1 = csc[i + 1] - x
            if diff1 % 2 == 0:
                return i + 1
            return i + 2

print(solve(csc, x))

